t.script:
function getLocationAndSubmit(form, event) {
    try {
        console.log('[GuardPro Mobile] getLocationAndSubmit called');
        console.log('[GuardPro Mobile] Form:', form);
        console.log('[GuardPro Mobile] Event:', event);

        // Safety check: if form or event is missing, allow normal submission
        if (!form || !event) {
            console.warn('[GuardPro Mobile] Form or event missing, allowing normal submission');
            return true;
        }

        if (navigator.geolocation) {
            console.log('[GuardPro Mobile] Geolocation available, preventing default');
            event.preventDefault();
            event.stopPropagation();

            const latField = form.querySelector('[name="latitude"]');
            const lngField = form.querySelector('[name="longitude"]');

            console.log('[GuardPro Mobile] Latitude field:', latField);
            console.log('[GuardPro Mobile] Longitude field:', lngField);

            // Show loading state
            const submitBtn = form.querySelector('button[type="submit"]');
            const originalText = submitBtn ? submitBtn.innerHTML : '';
            const originalDisabled = submitBtn ? submitBtn.disabled : false;

            if (submitBtn) {
                submitBtn.disabled = true;
                submitBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Getting location...';
            }

            // Set a timeout to ensure form submits even if geolocation hangs
            const submitTimeout = setTimeout(function() {
                console.warn('[GuardPro Mobile] Location timeout, submitting form without location');
                if (submitBtn) {
                    submitBtn.disabled = originalDisabled;
                    submitBtn.innerHTML = originalText;
                }
                try {
                    form.submit();
                } catch (e) {
                    console.error('[GuardPro Mobile] Error submitting form:', e);
                    // Last resort: trigger click on submit button
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.click();
                    }
                }
            }, 6000); // 6 second timeout

            navigator.geolocation.getCurrentPosition(
                function(position) {
                    clearTimeout(submitTimeout);
                    console.log('[GuardPro Mobile] Location captured:', position.coords.latitude, position.coords.longitude);
                    if (latField) latField.value = position.coords.latitude;
                    if (lngField) lngField.value = position.coords.longitude;

                    if (submitBtn) {
                        submitBtn.disabled = originalDisabled;
                        submitBtn.innerHTML = originalText;
                    }

                    try {
                        form.submit();
                    } catch (e) {
                        console.error('[GuardPro Mobile] Error submitting form after location:', e);
                        // Last resort: trigger click on submit button
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.click();
                        }
                    }
                },
                function(error) {
                    clearTimeout(submitTimeout);
                    // Submit without location on error
                    console.warn('[GuardPro Mobile] Location error:', error);
                    if (submitBtn) {
                        submitBtn.disabled = originalDisabled;
                        submitBtn.innerHTML = originalText;
                    }

                    // Submit form anyway
                    try {
                        form.submit();
                    } catch (e) {
                        console.error('[GuardPro Mobile] Error submitting form after location error:', e);
                        // Last resort: trigger click on submit button
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.click();
                        }
                    }
                },
                { timeout: 5000, enableHighAccuracy: true, maximumAge: 30000 }
            );
            return false;
        } else {
            console.log('[GuardPro Mobile] Geolocation not available, submitting form directly');
            return true; // Allow normal form submission
        }
    } catch (error) {
        console.error('[GuardPro Mobile] Error in getLocationAndSubmit:', error);
        // On any error, allow normal form submission
        return true;
    }
}

// Ensure function is available globally
window.getLocationAndSubmit = getLocationAndSubmit;
console.log('[GuardPro Mobile] getLocationAndSubmit function defined and available globally');

// Check if GPS tracker is available
if (typeof window.gpsTracker !== 'undefined') {
    console.log('[GuardPro Mobile] GPS tracker available');

    // Function to request location permission (must be called from user interaction)
    window.requestLocationPermission = function() {
        if (!navigator.geolocation) {
            alert('Geolocation is not supported by your browser');
            return;
        }

        console.log('[GuardPro Mobile] Requesting location permission (user clicked button)...');

        // Request permission - this MUST be triggered by user interaction
        navigator.geolocation.getCurrentPosition(
            function(position) {
                console.log('[GuardPro Mobile] ✓ Location permission GRANTED');
                console.log('[GuardPro Mobile] Current location:', position.coords.latitude, position.coords.longitude);

                // Hide permission banner
                const banner = document.getElementById('location-permission-banner');
                if (banner) banner.style.display = 'none';

                // Start GPS tracking now that we have permission
                console.log('[GuardPro Mobile] Starting GPS tracker...');
                window.gpsTracker.startTracking();

                // Show success message
                const successAlert = document.createElement('div');
                successAlert.className = 'alert alert-success alert-dismissible fade show mb-3';
                successAlert.innerHTML = '<i class="fa fa-check-circle me-2"></i><strong>Location tracking enabled!</strong> Your location will be updated automatically every 5 minutes. <button type="button" class="btn-close" data-bs-dismiss="alert"></button>';
                const container = document.querySelector('.container-fluid.p-3');
                if (container) {
                    container.insertBefore(successAlert, container.firstChild);
                    setTimeout(function() { 
                        if (successAlert.parentNode) successAlert.remove(); 
                    }, 8000);
                }

                // Store permission status
                localStorage.setItem('gps_permission_granted', 'true');
            },
            function(error) {
                console.error('[GuardPro Mobile] ✗ Location permission DENIED:', error);
                let errorMsg = '⚠️ Location Access Denied\n\n';
                if (error.code === 1) {
                    errorMsg += 'You blocked location access. To enable:\n\n';
                    errorMsg += '1. Click the lock icon in your browser address bar\n';
                    errorMsg += '2. Allow location access\n';
                    errorMsg += '3. Refresh this page';
                } else if (error.code === 2) {
                    errorMsg += 'Location information is unavailable. Please check your device settings.';
                } else if (error.code === 3) {
                    errorMsg += 'Location request timed out. Please try again.';
                }
                alert(errorMsg);
            },
            { 
                enableHighAccuracy: true, 
                timeout: 10000, 
                maximumAge: 0 
            }
        );
    };

    // Check permission status using Permissions API (if supported)
    async function checkLocationPermission() {
        console.log('[GuardPro Mobile] Checking location permission status...');

        // Check localStorage first
        if (localStorage.getItem('gps_permission_granted') === 'true') {
            console.log('[GuardPro Mobile] Permission previously granted, attempting to start tracking...');
            try {
                window.gpsTracker.startTracking();
                return true;
            } catch (e) {
                console.warn('[GuardPro Mobile] Could not start tracking:', e);
            }
        }

        // Try Permissions API if available
        if (navigator.permissions && navigator.permissions.query) {
            try {
                const result = await navigator.permissions.query({ name: 'geolocation' });
                console.log('[GuardPro Mobile] Permission state:', result.state);

                if (result.state === 'granted') {
                    console.log('[GuardPro Mobile] Permission granted, starting tracker...');
                    window.gpsTracker.startTracking();
                    return true;
                } else if (result.state === 'prompt' || result.state === 'denied') {
                    console.log('[GuardPro Mobile] Permission not granted, showing banner...');
                    const banner = document.getElementById('location-permission-banner');
                    if (banner) banner.style.display = 'block';
                    return false;
                }
            } catch (e) {
                console.warn('[GuardPro Mobile] Permissions API not fully supported:', e);
            }
        }

        // Fallback: just show the banner
        console.log('[GuardPro Mobile] Cannot determine permission status, showing banner...');
        const banner = document.getElementById('location-permission-banner');
        if (banner) banner.style.display = 'block';
        return false;
    }

    // Check permission on page load
    checkLocationPermission();

} else {
    console.warn('[GuardPro Mobile] GPS tracker not available - gps_tracker.js may not be loaded');
}

// Panic Button Hold-to-Activate
let panicHoldTimer = null;
let panicHoldStartTime = null;
let panicAnimationFrame = null;

window.startPanicHold = function(event) {
    event.preventDefault();

    const button = document.getElementById('panicButton');
    const progress = document.getElementById('panicProgress');
    const text = document.getElementById('panicButtonText');
    const form = document.getElementById('panicForm');

    // Vibrate on touch start (if supported)
    if ('vibrate' in navigator) {
        navigator.vibrate(50);
    }

    panicHoldStartTime = Date.now();
    const holdDuration = 3000; // 3 seconds

    // Update progress bar animation
    function updateProgress() {
        const elapsed = Date.now() - panicHoldStartTime;
        const percentage = Math.min((elapsed / holdDuration) * 100, 100);

        if (progress) {
            progress.style.height = percentage + '%';
        }

        if (text) {
            const remaining = Math.ceil((holdDuration - elapsed) / 1000);
            if (remaining > 0) {
                text.textContent = 'Hold ' + remaining + 's';
            } else {
                text.textContent = 'Sending...';
            }
        }

        if (elapsed < holdDuration) {
            panicAnimationFrame = requestAnimationFrame(updateProgress);
        }
    }

    updateProgress();

    // Set timer for full hold
    panicHoldTimer = setTimeout(function() {
        console.log('[GuardPro] Panic button held for 3 seconds - triggering alert');

        // Strong vibration pattern for confirmation
        if ('vibrate' in navigator) {
            navigator.vibrate([200, 100, 200, 100, 200]);
        }

        // Visual confirmation
        if (button) {
            button.classList.add('animate__animated', 'animate__pulse');
        }
        if (text) {
            text.textContent = 'SENDING!';
        }

        // Get location and submit
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                function(position) {
                    document.getElementById('panic-lat').value = position.coords.latitude;
                    document.getElementById('panic-lng').value = position.coords.longitude;
                    form.submit();
                },
                function(error) {
                    console.warn('Could not get location for panic:', error);
                    form.submit();
                },
                { timeout: 3000, enableHighAccuracy: true }
            );
        } else {
            form.submit();
        }
    }, holdDuration);
};

window.cancelPanicHold = function() {
    if (panicHoldTimer) {
        clearTimeout(panicHoldTimer);
        panicHoldTimer = null;
    }

    if (panicAnimationFrame) {
        cancelAnimationFrame(panicAnimationFrame);
        panicAnimationFrame = null;
    }

    const progress = document.getElementById('panicProgress');
    const text = document.getElementById('panicButtonText');

    if (progress) {
        progress.style.transition = 'height 0.2s ease-out';
        progress.style.height = '0%';
        setTimeout(function() {
            progress.style.transition = 'none';
        }, 200);
    }

    if (text) {
        text.textContent = 'Hold for 3s';
    }

    panicHoldStartTime = null;
};

